import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
const qGold=Color(0xFFE8D39A),qGreen=Color(0xFF073B2B),qBg=Color(0xFF071B16);
class QuranPage extends StatefulWidget{const QuranPage({super.key});@override State<QuranPage> createState()=>_QuranPageState();}
class _QuranPageState extends State<QuranPage>{
 final player=AudioPlayer();late final StreamSubscription<void> completeSub;
 List<Map<String,dynamic>> surahs=[],ayahs=[];int surahNo=1,ayahIndex=0;
 String reciter='ar.alafasy',reciterName='مشاري العفاسي',error='',tafsir='';
 bool loading=true,playing=false,loadingTafsir=false;Duration position=Duration.zero,duration=Duration.zero;List<String> bookmarks=[];
 static const reciters=<String,String>{'ar.alafasy':'مشاري العفاسي','ar.abdulbasit':'عبد الباسط عبد الصمد','ar.husary':'محمود خليل الحصري','ar.minshawi':'محمد صديق المنشاوي'};
 static const meanings=< (String,String,String)>[
 ('الصمد','الإخلاص','السيد الكامل المقصود في الحوائج، الذي لا يحتاج إلى أحد.'),('الكوثر','الكوثر','الخير الكثير.'),('الفلق','الفلق','الصبح وانفلاق النور بعد الظلام.'),('غاسق','الفلق','الليل إذا اشتد ظلامه.'),('الوسواس','الناس','من يلقي الخواطر السيئة في الصدور.'),('الطارق','الطارق','النجم الذي يظهر ليلاً.'),('الثاقب','الطارق','المضيء النافذ ضوؤه.'),('الغاشية','الغاشية','القيامة التي تغشى الناس بأهوالها.'),('سجى','الضحى','سكن واشتد هدوؤه.'),('دحاها','النازعات','بسطها ومهّدها.'),('مدهامتان','الرحمن','شديدتا الخضرة.'),('أبًّا','عبس','النبات والكلأ.'),('قَسْوَرَة','المدثر','قيل الأسد، وقيل الرماة.'),('الأخدود','البروج','شق طويل في الأرض.'),('سندس','الكهف','حرير رقيق.'),('إستبرق','الكهف','حرير غليظ فاخر.'),('أواب','ص','كثير الرجوع إلى الله والتوبة.'),('قانتين','مواضع متعددة','خاضعين مطيعين لله.')];
 @override void initState(){super.initState();completeSub=player.onPlayerComplete.listen((_)=>_next());player.onPositionChanged.listen((p){if(mounted)setState(()=>position=p);});player.onDurationChanged.listen((d){if(mounted)setState(()=>duration=d);});_loadBookmarks();_loadSurahs();}
 Future<Map<String,dynamic>> getData(String path)async{final c=HttpClient()..connectionTimeout=const Duration(seconds:12);try{final r=await (await c.getUrl(Uri.https('api.alquran.cloud',path))).close().timeout(const Duration(seconds:18));final body=await r.transform(utf8.decoder).join();if(r.statusCode!=200)throw Exception('network');final j=jsonDecode(body) as Map<String,dynamic>;if(j['code']!=200)throw Exception('api');return Map<String,dynamic>.from(j['data'] as Map);}finally{c.close(force:true);}}
 Future<void> _loadSurahs()async{try{final d=await getData('/v1/surah');if(!mounted)return;surahs=(d as List).map((x)=>Map<String,dynamic>.from(x as Map)).toList();await _loadSurah(1);}catch(_){if(mounted)setState(()=>error='تعذر تحميل فهرس السور. تحقق من الإنترنت.');}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> _loadSurah(int n)async{setState((){loading=true;error='';tafsir='';playing=false;});await player.stop();try{final d=await getData('/v1/surah/'+n.toString()+'/'+reciter);final list=(d['ayahs'] as List).map((x)=>Map<String,dynamic>.from(x as Map)).toList();if(!mounted)return;setState((){surahNo=n;ayahs=list;ayahIndex=0;position=Duration.zero;duration=Duration.zero;});final p=await SharedPreferences.getInstance();await p.setInt('quran_last_surah',n);await p.setInt('quran_last_ayah',1);}catch(_){if(mounted)setState(()=>error='تعذر تحميل السورة أو الصوت. جرّب قارئاً آخر.');}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> _changeReciter(String? v)async{if(v==null)return;reciter=v;reciterName=reciters[v]!;await _loadSurah(surahNo);}
 Future<void> _play()async{if(ayahs.isEmpty)return;final url=ayahs[ayahIndex]['audio']?.toString()??'';if(url.isEmpty){setState(()=>error='التسجيل غير متاح لهذه الآية.');return;}try{await player.play(UrlSource(url));if(mounted)setState(()=>playing=true);}catch(_){if(mounted)setState(()=>error='تعذر تشغيل الصوت. تحقق من الإنترنت.');}}
 Future<void> _toggle()async{if(playing){await player.pause();if(mounted)setState(()=>playing=false);}else{await _play();}}
 Future<void> _next()async{if(ayahIndex+1>=ayahs.length){if(mounted)setState(()=>playing=false);return;}setState(()=>ayahIndex++);await _play();}
 Future<void> _prev()async{if(ayahIndex==0)return;setState(()=>ayahIndex--);await _play();}
 Future<void> _taf()async{if(ayahs.isEmpty)return;setState(()=>loadingTafsir=true);try{final n=ayahs[ayahIndex]['number'];final d=await getData('/v1/ayah/'+n.toString()+'/ar.muyassar');if(mounted)setState(()=>tafsir=d['text']?.toString()??'لم يتوفر شرح.');}catch(_){if(mounted)setState(()=>tafsir='تعذر جلب التفسير حالياً. راجع تفسيراً معتمداً.');}finally{if(mounted)setState(()=>loadingTafsir=false);}}
 Future<void> _loadBookmarks()async{final p=await SharedPreferences.getInstance();if(mounted)setState(()=>bookmarks=p.getStringList('quran_marks')??[]);}
 Future<void> _mark()async{final k='$surahNo:${ayahIndex+1}';if(bookmarks.contains(k))return;bookmarks=[...bookmarks,k];final p=await SharedPreferences.getInstance();await p.setStringList('quran_marks',bookmarks);if(mounted)setState((){});}
 Future<void> _openMark(String k)async{final a=k.split(':');await _loadSurah(int.tryParse(a[0])??1);if(!mounted||ayahs.isEmpty)return;setState(()=>ayahIndex=(int.tryParse(a[1])??1)-1);}
 String time(Duration d)=>'${d.inMinutes.remainder(60).toString().padLeft(2,'0')}:${d.inSeconds.remainder(60).toString().padLeft(2,'0')}';
 @override void dispose(){completeSub.cancel();player.dispose();super.dispose();}
 @override Widget build(BuildContext c)=>DefaultTabController(length:3,child:Scaffold(backgroundColor:qBg,appBar:AppBar(backgroundColor:qGreen,foregroundColor:qGold,title:const Text('القرآن الكريم'),bottom:const TabBar(tabs:[Tab(icon:Icon(Icons.menu_book),text:'التلاوة'),Tab(icon:Icon(Icons.translate),text:'معاني القرآن'),Tab(icon:Icon(Icons.bookmark),text:'محفوظاتي')])),body:TabBarView(children:[reader(),meaningPage(),savedPage()])));
 Widget reader(){final name=surahs.isEmpty?'السورة':surahs.firstWhere((s)=>s['number']==surahNo,orElse:()=>surahs.first)['name'].toString();final a=ayahs.isEmpty?null:ayahs[ayahIndex];return ListView(padding:const EdgeInsets.all(14),children:[
 const Text('اختر السورة والقارئ',style:TextStyle(color:qGold,fontWeight:FontWeight.bold)),
 if(surahs.isNotEmpty)DropdownButton<int>(isExpanded:true,value:surahNo,dropdownColor:qGreen,items:surahs.map((s)=>DropdownMenuItem<int>(value:s['number'] as int,child:Text('${s['number']}. ${s['name']}'))).toList(),onChanged:(v){if(v!=null)_loadSurah(v);}),
 DropdownButton<String>(isExpanded:true,value:reciter,dropdownColor:qGreen,items:reciters.entries.map((e)=>DropdownMenuItem(value:e.key,child:Text(e.value))).toList(),onChanged:_changeReciter),
 if(error.isNotEmpty)Text(error,style:const TextStyle(color:Colors.orangeAccent)),
 if(loading)const Center(child:Padding(padding:EdgeInsets.all(24),child:CircularProgressIndicator(color:qGold))),
 if(a!=null)...[
 Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF174D37),Color(0xFF0D2C21)]),borderRadius:BorderRadius.circular(18),border:Border.all(color:qGold.withOpacity(.5))),child:Column(children:[Text(name,style:const TextStyle(color:qGold,fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:10),Text('الآية ${ayahIndex+1} من ${ayahs.length}',style:const TextStyle(color:Colors.white60)),const SizedBox(height:16),Text(a['text']?.toString()??'',textAlign:TextAlign.center,style:const TextStyle(fontFamily:'serif',fontSize:25,height:2.0)),const SizedBox(height:10),Text('القارئ: $reciterName',style:const TextStyle(color:qGold,fontSize:12))])),
 Row(mainAxisAlignment:MainAxisAlignment.center,children:[IconButton(onPressed:_prev,icon:const Icon(Icons.skip_previous,color:qGold,size:32)),IconButton(onPressed:_toggle,icon:Icon(playing?Icons.pause_circle:Icons.play_circle,color:qGold,size:52)),IconButton(onPressed:_next,icon:const Icon(Icons.skip_next,color:qGold,size:32)),IconButton(onPressed:_mark,icon:Icon(bookmarks.contains('$surahNo:${ayahIndex+1}')?Icons.bookmark:Icons.bookmark_add_outlined,color:qGold))]),
 Slider(value:duration.inMilliseconds==0?0:position.inMilliseconds.clamp(0,duration.inMilliseconds).toDouble(),max:duration.inMilliseconds==0?1:duration.inMilliseconds.toDouble(),onChanged:duration.inMilliseconds==0?null:(v)=>player.seek(Duration(milliseconds:v.round())),activeColor:qGold),
 Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(time(position),style:const TextStyle(color:Colors.white60)),Text(time(duration),style:const TextStyle(color:Colors.white60))]),
 OutlinedButton.icon(onPressed:_taf,icon:const Icon(Icons.lightbulb_outline),label:const Text('معنى وتفسير الآية')),
 if(loadingTafsir)const Center(child:CircularProgressIndicator(color:qGold)),
 if(tafsir.isNotEmpty)Card(color:const Color(0xFF17382C),child:Padding(padding:const EdgeInsets.all(14),child:Text(tafsir,style:const TextStyle(height:1.8)))),
 const Text('يتقدم مؤشر الآية تلقائياً عند انتهاء المقطع الصوتي، ويمكنك التنقل داخل الآية من شريط الصوت.',style:TextStyle(color:Colors.white54,fontSize:11,height:1.6))
 ]]);}
 Widget meaningPage()=>ListView(padding:const EdgeInsets.all(14),children:[const Text('معاني مفردات قرآنية مختارة',style:TextStyle(color:qGold,fontSize:20,fontWeight:FontWeight.w900)),const Text('هذه معانٍ موجزة لبعض المفردات وليست بديلاً عن كتب التفسير المعتمدة.',style:TextStyle(color:Colors.white60,height:1.6)),...meanings.map((m)=>Card(color:qGreen,child:ListTile(title:Text(m.$1,style:const TextStyle(color:qGold,fontWeight:FontWeight.bold)),subtitle:Text(m.$2+' • '+m.$3,style:const TextStyle(height:1.6)))))]);
 Widget savedPage()=>ListView(padding:const EdgeInsets.all(14),children:[const Text('علامات الحفظ',style:TextStyle(color:qGold,fontSize:20,fontWeight:FontWeight.w900)),const Text('تُحفظ العلامات على هذا الهاتف.',style:TextStyle(color:Colors.white60)),if(bookmarks.isEmpty)const Text('لم تحفظ آيات بعد.'),...bookmarks.map((k)=>Card(color:qGreen,child:ListTile(title:Text('السورة ${k.split(':')[0]} • الآية ${k.split(':')[1]}'),leading:const Icon(Icons.bookmark,color:qGold),onTap:()=>_openMark(k),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{bookmarks.remove(k);final p=await SharedPreferences.getInstance();await p.setStringList('quran_marks',bookmarks);if(mounted)setState((){});}))))]);
}
